[ "$2" = 0 ] || { echo "/boot/grub/grub.cfg uid $2"; exit 1; }
case " 0 " in *" $3 "*) echo compliant ;; *) echo "/boot/grub/grub.cfg gid $3" ;; esac

f=/boot/grub/grub.cfg; [ -r "$f" ] || exit 1
grep -q '^set superusers' "$f" || { echo 'no superusers in grub.cfg'; exit 1; }
grep -Eq '^\s*password(_pbkdf2)?\s' "$f" && echo compliant || echo 'no bootloader password in grub.cfg'

bad=0
chk() { case $1 in net.ipv6.*) [ -d /proc/sys/net/ipv6 ] || return 0 ;; esac
