  sed -i -E '/^[[:space:]]*UMASK[[:space:]]/d' /etc/login.defs; printf 'UMASK\t\t027\n' >> /etc/login.defs; fi
mkdir -p /etc/profile.d
printf '# CIS: default umask\numask 027\n' > /etc/profile.d/50-tmaegis-umask.sh
true

